// Jede eingegangene Mail für das Portal aufbereiten. Das Portal entscheidet, ob es eine Unzustellbar-Meldung,
// eine Abwesenheitsnotiz oder eine Antwort auf eine gesendete E-Mail ist – alles andere verwirft es, gespeichert wird kein Inhalt.
const text = (v) => {
  if (v == null) return '';
  if (typeof v === 'string') return v;
  if (Array.isArray(v)) return v.map(text).join(' ');
  if (typeof v === 'object') return v.text || v.address || (Array.isArray(v.value) ? v.value.map((x) => x.address || '').join(', ') : '') || '';
  return String(v);
};
return $input.all().map((item) => {
  const j = item.json || {};
  // je nach n8n-Version liegen die Kopfzeilen direkt im Objekt, unter metadata oder unter headers
  const h = Object.assign({}, j.headers || {}, j.metadata || {}, j);
  const kopf = (...namen) => { for (const n of namen) { const w = text(h[n]); if (w) return w; } return ''; };
  const html = text(j.textHtml || j.html).replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ');
  return { json: {
    postfach: kopf('delivered-to', 'x-original-to', 'to'),
    von: kopf('from'),
    betreff: kopf('subject'),
    datum: kopf('date'),
    message_id: kopf('message-id', 'messageId'),
    in_reply_to: kopf('in-reply-to', 'inReplyTo'),
    references: kopf('references'),
    auto: kopf('auto-submitted'),
    text: (text(j.textPlain || j.text) || html).slice(0, 50000),
  } };
});
